function haloText(parent, text, x, y, size, weight, anchor) {
  return parent.text(text)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, weight: weight || 'normal', anchor: anchor || 'middle' })
    .move(x, y)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round', fill: '#000' });
}

function labelBox(parent, text, x, y, size, anchor) {
  var g = parent.group();
  var t = g.text(text).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size || 15,
    anchor: anchor || 'start'
  }).move(x, y).fill('#111');
  var b = t.bbox(), pad = 5;
  g.rect(b.width + pad * 2, b.height + pad * 2)
    .move(b.x - pad, b.y - pad + 1)
    .fill({ color: '#fff', opacity: 0.82 })
    .stroke({ color: '#d7d7d7', width: 0.8 })
    .back();
  return g;
}

function callout(parent, text, x, y, tx, ty, size) {
  var g = parent.group();
  g.line(tx, ty, x, y + 10).stroke({ color: '#666', width: 1.2, dasharray: '3,3' });
  return labelBox(g, text, x, y, size || 14, 'start');
}

function starburst(parent, x, y, r, opacity, tooltipText) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var pts = [];
  for (var i = 0; i < 28; i++) {
    var a = -Math.PI / 2 + i * Math.PI * 2 / 28;
    var rr = (i % 2 === 0) ? r : r * 0.34;
    pts.push((x + Math.cos(a) * rr) + ',' + (y + Math.sin(a) * rr));
  }
  g.polygon(pts.join(' '))
    .fill('#ffe56a')
    .stroke({ color: '#ffd45a', width: 0.8, opacity: 0.8 });
  g.circle(r * 0.65).center(x, y).fill({ color: '#fff7a8', opacity: 0.8 });
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tooltipText || 'Fission event: a captured neutron releases more neutrons.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Fission event', 'A neutron captured by a fissile nucleus can cause fission. The fission releases energy and additional neutrons that may either escape or cause later fissions.');
    });
  return g;
}

function arrow(parent, x1, y1, x2, y2, width, opacity, tooltipText) {
