    .stroke({ color: '#000', width: width || 4, linecap: 'round' })
    .attr({ 'marker-end': arrowMarker.url(), opacity: opacity == null ? 1 : opacity });
  ln.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tooltipText || 'Neutron path', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Neutron path', 'A neutron path is productive only if it remains in the material long enough to be captured by another fissile nucleus. Paths that leave the boundary remove neutrons from the chain reaction.');
    });
  return ln;
}

function panelPoint(panel, r, p) {
  return [panel.cx + p[0] * r, panel.cy + p[1] * r];
}

function massRadiusFor(type) {
  if (type === 'sub') {
    return (selectedCase === 'Sub-critical mass') ? 90 + 80 * fissileMass : panels.sub.baseR;
  }
  return (selectedCase === 'Critical mass') ? 120 + 90 * fissileMass : panels.crit.baseR;
}

function escapeFraction(r, type) {
  if (type === 'crit') {
    return Math.max(0.18, Math.min(0.55, 0.78 - 0.00255 * r));
  }
  return Math.max(0.38, Math.min(0.78, 0.95 - 0.00205 * r));
}

function drawIndicator(parent, panel, r, type) {
  var escape = escapeFraction(r, type);
  var capture = 1 - escape;
  var x = panel.cx - 72, y = (type === 'crit') ? 480 : 444, w = 144, h = 13;
  var g = parent.group();
  g.rect(w + 10, 46).move(x - 5, y - 20).fill({ color: '#fff', opacity: 0.78 }).stroke({ color: '#ddd', width: 0.7 });
