    .font({ family: 'Arial, Helvetica, sans-serif', size: 12, anchor: 'middle' })
    .center(panel.cx, y - 9)
    .fill('#222');
  g.rect(w * escape, h).move(x, y).fill('#5b5b5b');
  g.rect(w * capture, h).move(x + w * escape, y).fill('#f1c84b');
  g.rect(w, h).move(x, y).fill('none').stroke({ color: '#111', width: 0.8 });
  g.text(Math.round(escape * 100) + '% escape')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 11, anchor: 'start' })
    .move(x, y + 15)
    .fill('#333');
  g.text(Math.round(capture * 100) + '% productive')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 11, anchor: 'end' })
    .move(x + w, y + 15)
    .fill('#333');
