function drawRadiusGauge(parent, panel, r, selected) {
  if (!selected) return;
  var g = parent.group();
  var angle = -Math.PI / 5;
  var x2 = panel.cx + Math.cos(angle) * r * 0.82;
  var y2 = panel.cy + Math.sin(angle) * r * 0.82;
  g.line(panel.cx, panel.cy, x2, y2).stroke({ color: '#334078', width: 2, dasharray: '5,4' });
