function drawPanel(parent, type) {
  var panel = type === 'sub' ? panels.sub : panels.crit;
  var r = massRadiusFor(type);
  var isSelected = (type === 'sub' && selectedCase === 'Sub-critical mass') ||
                   (type === 'crit' && selectedCase === 'Critical mass');

  haloText(parent, panel.title, panel.cx, 12, 26, '700', 'middle');
  haloText(parent, panel.label, panel.cx, 504, 24, 'normal', 'middle');

  var circle = parent.circle(r * 2).center(panel.cx, panel.cy)
    .fill({ color: '#7f8cca', opacity: 0.84 })
    .stroke(isSelected ? { color: '#43559e', width: 3 } : { color: '#7f8cca', width: 0 });
  circle.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip(type === 'sub' ? 'Smaller mass: many neutrons reach the surface and escape.' : 'Larger mass: more neutron paths end in capture before escape.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(panel.title, type === 'sub'
        ? 'In a sub-critical sample, surface leakage is too high. Each fission generation produces too few successful follow-up fissions, so the chain reaction fades.'
