    });

  drawIncoming(parent, panel, r);

  var eventList = type === 'sub' ? subEvents : critEvents;
  var arrowList = type === 'sub' ? subArrows : critArrows;

  for (var a = 0; a < arrowList.length; a++) {
    var ap = arrowList[a];
    var p1 = panelPoint(panel, r, [ap[0], ap[1]]);
    var p2 = panelPoint(panel, r, [ap[2], ap[3]]);
    var vis = 1;
    if (type === 'crit' && animationGeneration !== null) {
      vis = ap[4] <= animationGeneration ? 1 : 0.10;
    }
    var escapeTip = Math.sqrt(ap[2] * ap[2] + ap[3] * ap[3]) > 1.02;
    arrow(parent, p1[0], p1[1], p2[0], p2[1], 4, vis,
      escapeTip ? 'Escaping neutron: it leaves the material and cannot continue the chain.' :
                  'Productive neutron path: it remains inside long enough to trigger another fission.');
  }

  for (var i = 0; i < eventList.length; i++) {
    var ep = eventList[i];
    var pp = panelPoint(panel, r, ep);
    var op = 1;
    if (type === 'crit' && animationGeneration !== null) {
      op = ep[2] <= animationGeneration ? 1 : 0.10;
    }
    starburst(parent, pp[0], pp[1], type === 'sub' ? 27 : 29, op,
      'Generation ' + ep[2] + ' fission event.');
  }

  drawRadiusGauge(parent, panel, r, isSelected);
  drawIndicator(parent, panel, r, type);

  if (type === 'sub') {
    callout(parent, 'high escape fraction', panel.cx - 140, panel.cy - 210, panel.cx - r * 0.95, panel.cy - r * 0.35, 14);
    callout(parent, 'limited, dying chain', panel.cx - 118, panel.cy + 168, panel.cx - r * 0.15, panel.cy + r * 0.35, 14);
  } else {
    callout(parent, 'low escape fraction', panel.cx + 85, panel.cy - 232, panel.cx + r * 0.66, panel.cy - r * 0.18, 14);
    callout(parent, 'self-sustaining chain', panel.cx - 120, panel.cy - 232, panel.cx - r * 0.05, panel.cy - r * 0.35, 14);
  }
}

function updateScene() {
  scene.clear();
  var bg = scene.rect(VW, VH).fill('#fff');
  bg.back();
  drawPanel(scene, 'sub');
  drawPanel(scene, 'crit');
}

function clearCascadeTimers() {
  for (var i = 0; i < cascadeTimers.length; i++) clearTimeout(cascadeTimers[i]);
  cascadeTimers = [];
}

function update_fissileMass(v) {
  clearCascadeTimers();
  animationGeneration = null;
  fissileMass = v;
  updateScene();
}

function toggle_massView(on) {
  clearCascadeTimers();
  animationGeneration = null;
  selectedCase = on ? 'Critical mass' : 'Sub-critical mass';
  updateScene();
}

function trigger_chainCascade() {
  clearCascadeTimers();
  selectedCase = 'Critical mass';
  fissileMass = 1;
  document.getElementById('massViewInput').checked = true;
  document.getElementById('fissileMassInput').value = '1';
  document.getElementById('fissileMassVal').value = '1';
  animationGeneration = -1;
  updateScene();

  [0, 1, 2, 3].forEach(function (gen, idx) {
    cascadeTimers.push(setTimeout(function () {
      animationGeneration = gen;
      updateScene();
      if (gen === 3) {
        cascadeTimers.push(setTimeout(function () {
          animationGeneration = null;
          updateScene();
        }, 900));
      }
    }, 420 + idx * 850));
  });
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  clearCascadeTimers();
  animationGeneration = null;
  var step = demoSteps[currentStep];

  selectedCase = step.state.massView;
  fissileMass = step.state.fissileMass;

  document.getElementById('massViewInput').checked = selectedCase === 'Critical mass';
  document.getElementById('fissileMassInput').value = String(fissileMass);
  document.getElementById('fissileMassVal').value = String(fissileMass);
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ' — ' + step.title;

  updateScene();

  if (currentStep === 3) {
    cascadeTimers.push(setTimeout(function () { trigger_chainCascade(); }, 500));
  }
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

