function titleText(parent, text, x, y, size, weight) {
  var t = parent.text(text)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, weight: weight || '700', anchor: 'middle' })
    .fill('#000')
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function starburst(parent, x, y, r, opacity, tooltipText) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var pts = [];
  for (var i = 0; i < 36; i++) {
    var a = -Math.PI / 2 + i * Math.PI * 2 / 36;
    var rr = (i % 2 === 0) ? r : r * 0.25;
    pts.push((x + Math.cos(a) * rr) + ',' + (y + Math.sin(a) * rr));
  }
  g.polygon(pts.join(' '))
    .fill('#ffe06a')
    .stroke({ color: '#ffd56a', width: 0.7, opacity: 0.75 });
  g.circle(r * 0.56).center(x, y).fill({ color: '#fff2a0', opacity: 0.88 }).stroke('none');
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tooltipText || 'Fission event: a captured neutron releases more neutrons.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Fission event', 'A neutron captured by a fissile nucleus can cause fission. The event releases energy and additional neutrons that may either escape or trigger later fissions.');
    });
  return g;
}

function arrow(parent, x1, y1, x2, y2, width, opacity, tooltipText) {
  var ln = parent.line(x1, y1, x2, y2)
    .stroke({ color: '#000', width: width || 4, linecap: 'square' })
    .attr({ 'marker-end': 'url(#neutronArrowHead)' })
    .opacity(opacity == null ? 1 : opacity);
  ln.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tooltipText || 'Neutron path', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Neutron path', 'A neutron continues the chain only if it is captured before it leaves the fissile material. Critical mass is the size at which enough neutron paths remain productive to replace losses.');
    });
  return ln;
}

function panelPoint(panel, r, p) {
  return [panel.cx + p[0] * r, panel.cy + p[1] * r];
}

function massRadiusFor(type) {
  if (type === 'sub') {
    if (selectedCase === 'Sub-critical mass') return 90 + 80 * fissileMass;
    return panels.sub.baseR;
  }
  if (selectedCase === 'Critical mass') return 120 + 90 * fissileMass;
  return panels.crit.baseR;
}

function escapeFraction(r, type) {
  if (type === 'crit') return Math.max(0.18, Math.min(0.48, 0.74 - 0.00225 * r));
  return Math.max(0.40, Math.min(0.78, 0.94 - 0.00195 * r));
}

function drawIncoming(parent, panel, r, type) {
  var nx = panel.cx - r * 0.94;
  var ny = panel.cy - r * 0.86;
  var tx = panel.cx - r * 0.45;
  var ty = panel.cy - r * 0.40;
  var g = parent.group();
  g.circle(21).center(nx, ny)
    .fill({ color: '#d7d7bd', opacity: 0.95 })
    .stroke({ color: '#b7b79d', width: 1.2, opacity: 0.8 });
  arrow(g, nx + 16, ny + 12, tx, ty, 4, 1, 'Incoming neutron entering the fissile material.');
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Incoming neutron: the particle that begins this chain.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Incoming neutron', 'A chain reaction begins when a neutron enters fissile material and is captured by a nucleus. Whether the chain grows depends on how many later neutrons are captured instead of escaping.');
    });
}

function drawRadiusIndicator(parent, panel, r, type) {
  var selected = (type === 'sub' && selectedCase === 'Sub-critical mass') || (type === 'crit' && selectedCase === 'Critical mass');
  var cleanDefault = selectedCase === 'Sub-critical mass' && Math.abs(fissileMass - 0.6) < 0.001 && animationGeneration === null;
  if (!selected || cleanDefault) return;
  var angle = -Math.PI / 5;
  var x2 = panel.cx + Math.cos(angle) * r * 0.78;
  var y2 = panel.cy + Math.sin(angle) * r * 0.78;
  var g = parent.group().opacity(0.72);
  g.line(panel.cx, panel.cy, x2, y2).stroke({ color: '#263a8a', width: 2, dasharray: '6,5' });
  g.circle(5).center(panel.cx, panel.cy).fill('#263a8a');
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Mass/radius indicator: increasing mass increases the distance neutrons travel before reaching the surface.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Mass and radius', 'A larger fissile sample has a smaller surface area relative to its volume. Neutrons are then less likely to reach the surface quickly, so a larger fraction can cause another fission.');
    });
}

function drawPanel(parent, type) {
  var panel = type === 'sub' ? panels.sub : panels.crit;
  var r = massRadiusFor(type);

  titleText(parent, panel.title, panel.cx, 24, 26, '700');
  titleText(parent, panel.label, panel.cx, 519, 25, '400');

  var circle = parent.circle(r * 2).center(panel.cx, panel.cy)
    .fill({ color: '#7f8cca', opacity: 0.86 })
    .stroke('none');
  circle.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      var txt = type === 'sub'
        ? 'Sub-critical mass: many neutron paths reach the surface and escape.'
        : 'Critical mass: enough neutron paths are captured to sustain the chain.';
      showTooltip(txt, e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(panel.title, type === 'sub'
        ? 'In a sub-critical sample, too many neutrons leave the material before causing another fission. Each generation produces too few follow-up fissions, so the chain reaction dies out.'
        : 'At critical mass, neutron capture keeps pace with neutron escape and other losses. The reaction can sustain itself because each generation can cause the next.');
    });

  drawIncoming(parent, panel, r, type);

  var arrowList = type === 'sub' ? subArrows : critArrows;
  for (var a = 0; a < arrowList.length; a++) {
    var ap = arrowList[a];
    var p1 = panelPoint(panel, r, [ap[0], ap[1]]);
    var p2 = panelPoint(panel, r, [ap[2], ap[3]]);
    var op = 1;
    if (type === 'crit' && animationGeneration !== null) op = ap[4] <= animationGeneration ? 1 : 0.08;
    var escapeTip = Math.sqrt(ap[2] * ap[2] + ap[3] * ap[3]) > 1.02;
    arrow(parent, p1[0], p1[1], p2[0], p2[1], 4, op,
      escapeTip ? 'Escaping neutron: it leaves the blue fissile region.' :
                  'Captured/productive path: this neutron can help trigger another fission.');
  }

  var eventList = type === 'sub' ? subEvents : critEvents;
  for (var i = 0; i < eventList.length; i++) {
    var ep = eventList[i];
    var pp = panelPoint(panel, r, ep);
    var eventOpacity = 1;
    if (type === 'crit' && animationGeneration !== null) eventOpacity = ep[2] <= animationGeneration ? 1 : 0.08;
    starburst(parent, pp[0], pp[1], type === 'sub' ? 27 : 29, eventOpacity,
      'Generation ' + ep[2] + ' fission event.');
  }

  drawRadiusIndicator(parent, panel, r, type);
}

function clearCascadeTimers() {
  for (var i = 0; i < cascadeTimers.length; i++) clearTimeout(cascadeTimers[i]);
  cascadeTimers = [];
}

function updateReadout() {
  var type = selectedCase === 'Critical mass' ? 'crit' : 'sub';
  var r = massRadiusFor(type);
  var esc = escapeFraction(r, type);
  var captured = 1 - esc;
  var text;
  if (type === 'sub') {
    text = 'High escape fraction: about ' + Math.round(esc * 100) + '% escape, so only about ' + Math.round(captured * 100) + '% remain productive.';
  } else {
    text = 'Low escape fraction: about ' + Math.round(esc * 100) + '% escape, so about ' + Math.round(captured * 100) + '% remain productive.';
  }
  var readout = document.getElementById('escapeCaptureReadout');
  if (readout) readout.textContent = text;
  var mv = document.getElementById('massViewVal');
  if (mv) mv.value = selectedCase;
}

function updateScene() {
  scene.clear();
  scene.rect(VW, VH).fill('#fff');
  drawPanel(scene, 'sub');
  drawPanel(scene, 'crit');
  updateReadout();
}

function update_fissileMass(v) {
  clearCascadeTimers();
  animationGeneration = null;
  fissileMass = v;
  updateScene();
}

function toggle_massView(on) {
  clearCascadeTimers();
  animationGeneration = null;
  selectedCase = on ? 'Critical mass' : 'Sub-critical mass';
  updateScene();
}

function trigger_chainCascade() {
  clearCascadeTimers();
  selectedCase = 'Critical mass';
  fissileMass = 1;
  var viewInput = document.getElementById('massViewInput');
  var massInput = document.getElementById('fissileMassInput');
  var massVal = document.getElementById('fissileMassVal');
  if (viewInput) viewInput.checked = true;
  if (massInput) massInput.value = '1';
  if (massVal) massVal.value = '1';

  animationGeneration = -1;
  updateScene();

  [0, 1, 2, 3].forEach(function (gen, idx) {
    cascadeTimers.push(setTimeout(function () {
      animationGeneration = gen;
      updateScene();
      if (gen === 3) {
        cascadeTimers.push(setTimeout(function () {
          animationGeneration = null;
          updateScene();
        }, 1100));
      }
    }, 350 + idx * 850));
  });
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  clearCascadeTimers();
  animationGeneration = null;

  var step = demoSteps[currentStep];
  selectedCase = step.state.massView;
  fissileMass = step.state.fissileMass;

  var viewInput = document.getElementById('massViewInput');
  var massInput = document.getElementById('fissileMassInput');
  var massVal = document.getElementById('fissileMassVal');
  var narration = document.getElementById('demoNarration');
  var stepLabel = document.getElementById('stepLabel');

  if (viewInput) viewInput.checked = selectedCase === 'Critical mass';
  if (massInput) massInput.value = String(fissileMass);
  if (massVal) massVal.value = String(fissileMass);
  if (narration) narration.textContent = step.narration;
  if (stepLabel) stepLabel.textContent = (currentStep + 1) + '/' + demoSteps.length + ' — ' + step.title;

  updateScene();

  if (currentStep === 3) {
    cascadeTimers.push(setTimeout(function () { trigger_chainCascade(); }, 450));
  }
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

